// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.prank(alice);
        c.airDrop();
        // first call succeeds in both versions
        assertEq(c.tokenBalance(alice), 20);

        vm.prank(alice);
        // second call: reference reverts (hasNoBalance check fails), mutant succeeds
        bool ok;
        try c.airDrop() { ok = true; } catch { ok = false; }
        assertEq(ok, false); // reference: false; mutant: true, so this assertion fails on mutant
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);

        // First call to airDrop() succeeds for both reference and mutant
        vm.prank(alice);
        c.airDrop();

        // Second call to airDrop() from same address
        // In reference (with hasNoBalance), it reverts
        // In mutant (without hasNoBalance), it succeeds
        vm.prank(alice);
        // For reference, this call reverts; for mutant, it goes through
        // We use try/catch to capture the revert difference
        bool secondCallReverted = false;
        try c.airDrop() {
            secondCallReverted = false;
        } catch {
            secondCallReverted = true;
        }

        // In reference: second call reverts, so tokenBalance[alice] stays 20
        // In mutant: no revert, so tokenBalance[alice] becomes 40
        // Assert that reference behavior holds: second call reverts
        assertTrue(secondCallReverted);
    }
}
